/* Portfolio-wide costs and scenario contribution. Uses state and helpers from app.js. */
const COST_LABELS={commission:'Комісія від зборів',team:'Команда',it:'IT і зв’язок',overhead:'Накладні витрати',accounts:'Супровід усіх договорів',actions:'Внутрішні операції',legal:'Судові / виконавчі витрати',review:'Первинна перевірка',extra:'Інші календарні витрати'};
let potentialOrder='desc';
function expenseInput(key,label,unit='₴',step=100,min=0,max=''){
  return `<div class="expense-field"><label for="expense-${key}">${label}</label><div class="input-wrap"><input id="expense-${key}" data-param="${key}" type="number" min="${min}" ${max!==''?`max="${max}"`:''} step="${step}" aria-label="${label}"><span>${unit}</span></div></div>`;
}
function renderCosts(){
  if(!$('#expense-results')){
    $('#tab-costs').innerHTML=`<div class="notice">Рахуємо витрати по всьому пакету, включно з договорами без платежів і вимогами на перевірці. Два режими є альтернативними: деталізовані статті не додаються до єдиного відсотка спрощеної моделі.</div><div class="expense-layout"><div class="stack"><div class="panel expense-form"><div class="panel-heading"><div><h2>План витрат на портфель</h2><p>Це частка ресурсів, віднесена на цей пакет; суми є демонстраційними припущеннями.</p></div></div><label class="field-label" for="expense-cost_mode">Спосіб обліку</label><select id="expense-cost_mode" data-param="cost_mode"><option value="detailed">Деталізований бюджет</option><option value="simple">Єдиний відсоток від зборів</option></select><div class="expense-grid common-expenses">${expenseInput('cost_rate','Частка від зборів','%',1,0,99)}${expenseInput('startup','Початкові витрати у момент 0')}${expenseInput('expense_multiplier','Множник майбутніх витрат','%',5,0,300)}</div><div id="cost-mode-help" class="fine"></div><fieldset id="detailed-expenses"><legend>Регулярні витрати</legend><div class="expense-grid">${expenseInput('monthly_fixed','Команда / місяць')}${expenseInput('monthly_it','IT і зв’язок / місяць')}${expenseInput('monthly_overhead','Накладні / місяць')}${expenseInput('fixed_months','Тривалість бюджету','міс.',1,0,60)}${expenseInput('account_monthly','Супровід одного договору / місяць','₴',1)}${expenseInput('work_months','Тривалість супроводу','міс.',1,0,60)}</div><p class="fine">Затримка зборів подовжує обидва ненульові періоди витрат на відповідну кількість місяців. Бюджет після завершення активної роботи дорівнює нулю; пізні пасивні збори можуть продовжуватися.</p><legend>Окремі дії та юридична робота</legend><div class="expense-grid">${expenseInput('review_unit_cost','Перевірка одного договору','₴',1)}${expenseInput('action_unit_cost','Ціна внутрішньої операції','₴',1)}${expenseInput('actions_per_account','Операцій на кожен договір','дій',1)}${expenseInput('action_month','Місяць внутрішніх операцій','міс.',1,1,84)}${expenseInput('legal_share','Частка договорів у юридичній роботі','%',1,0,100)}${expenseInput('legal_unit_cost','Витрати на одну справу','₴',100)}${expenseInput('legal_month','Місяць юридичних витрат','міс.',1,1,84)}</div><p class="fine">Внутрішні операції та супровід — на всі договори, навіть без надходжень. Це не план контактів з особами. Юридичні витрати — на задану частку перевірених договорів; витрати задані на справу, а не як утримання з надходжень. Комісію виконавця, яку сплачує інша сторона, сюди не додають.</p></fieldset></div><div class="panel" id="extra-expense-panel"><h2>Календар інших витрат</h2><p class="fine">Додайте експертизу, зберігання документів чи іншу витрату стягнення. Кожна сума включається один раз у вибраному місяці.</p><div class="extra-form"><input id="extra-label" placeholder="Назва витрати" maxlength="120" aria-label="Назва додаткової витрати"><input id="extra-month" type="number" min="1" max="84" value="6" aria-label="Місяць додаткової витрати"><input id="extra-amount" type="number" min="0" value="50000" aria-label="Сума додаткової витрати"><button class="button primary" data-action="add-extra">Додати</button></div><div id="extra-expense-list"></div></div></div><div class="stack" id="expense-results"></div></div>`;
  }
  syncParams();
  const detailed=options.cost_mode==='detailed';
  $('#detailed-expenses').disabled=!detailed;$('#extra-expense-panel').hidden=!detailed;
  $('#cost-mode-help').textContent=detailed?'Частка від зборів — тільки комісія успіху. Команда, IT, супровід, дії та юридична робота враховані окремо. Не включайте їх повторно у комісію.':'Єдина частка замінює всі майбутні статті витрат. Початкові витрати залишаються окремими. У цьому режимі витрат при нульових зборах немає.';
  const r=result;
  $('#expense-results').innerHTML=`<div class="metrics expense-metrics">${metric('Всі витрати, без ціни',mln(r.cost_total),'З початковими витратами','emphasis')}${metric('Договори без платежів',mln(r.allocation.nonpayers),'Очікувана частка прямих витрат')}${metric('Пікова потреба у коштах',mln(r.funding_peak),'Покупка + початкові + касовий дефіцит')}${metric('Покриття повних витрат',num(r.coverage,2)+'<em> ×</em>','Збори / (ціна + всі витрати)')}</div><div class="panel"><div class="panel-heading"><div><h2>Куди йде бюджет</h2><p>Майбутні витрати з урахуванням множника ${num(options.expense_multiplier*100)}%</p></div></div><div class="table-wrap"><table><tbody>${Object.entries(COST_LABELS).map(([k,label])=>`<tr><td>${k==='commission'&&!detailed?'Єдина частка витрат':label}</td><td class="num">${money(r.category_totals[k])}</td></tr>`).join('')}<tr><td>Початкові витрати, момент 0</td><td class="num">${money(options.startup)}</td></tr><tr class="total-row"><td>Разом, без ціни покупки</td><td class="num">${money(r.cost_total)}</td></tr></tbody></table></div></div><div class="panel"><h2>Хто створює витрати</h2><div class="table-wrap"><table><tbody><tr><td>Договори з надходженнями*</td><td class="num">${money(r.allocation.payers)}</td></tr><tr><td>Договори без надходжень*</td><td class="num">${money(r.allocation.nonpayers)}</td></tr><tr><td>Вимоги на перевірці</td><td class="num">${money(r.allocation.review)}</td></tr><tr><td>Спільні + початкові витрати</td><td class="num">${money(r.allocation.shared)}</td></tr></tbody></table></div><p class="fine">* Сценарний розподіл прямих витрат за заданою ймовірністю платежу. Юридична активність умовно незалежна від майбутнього платежу. Це не фактичні витрати відомих платників / неплатників і не додаткова стаття бюджету.</p></div>`;
  $('#extra-expense-list').innerHTML=options.extra_costs.length?`<table><thead><tr><th>Подія</th><th class="num">Місяць</th><th class="num">Базова сума</th><th></th></tr></thead><tbody>${options.extra_costs.map((c,i)=>`<tr><td>${esc(c.label)}</td><td class="num">${c.month}</td><td class="num">${money(c.amount)}</td><td class="num"><button class="text-button" data-remove-extra="${i}" aria-label="Видалити витрату ${esc(c.label)}">×</button></td></tr>`).join('')}</tbody></table>`:'<p class="fine">Додаткових витрат ще немає.</p>';
}
function renderPotential(){
  const r=result,rank=[...r.records].filter(x=>x.quality==='ready').sort((a,b)=>(potentialOrder==='desc'?-1:1)*(a.contribution-b.contribution));
  const negative=rank.filter(x=>x.contribution<0).length;
  const segs=Object.entries(NPL.SEGMENTS).map(([k,s])=>{const d=r.segments[k]||{count:0,ready_count:0,payers:0,gross:0,contribution:0};const p=Math.min(1,s.payer*options.payer_multiplier);return `<tr><td>${s.label}</td><td class="num">${num(d.count)}</td><td class="num">${pct(p)}</td><td class="num">≈ ${num(d.payers)}</td><td class="num">${money(d.gross)}</td><td class="num">${money(d.contribution)}</td></tr>`;}).join('');
  $('#tab-potential').innerHTML=`<div class="notice">Сценарні частки платників і суми погашення задані по сегментах. Ранжування враховує суму вимоги, строки й прямі витрати, але не є індивідуальним ML-прогнозом. Одиниця аналізу — договір; один позичальник може мати кілька договорів.</div><div class="metrics">${metric('Договорів з платежами','≈ '+num(r.payers),'Очікування за заданими частками','emphasis')}${metric('Без платежів','≈ '+num(r.nonpayers),'Серед перевірених договорів')}${metric('Середні збори з платника',r.average_payer===null?'—':num(r.average_payer)+'<em> ₴</em>','Недисконтована сценарна сума')}${metric('Потрібно для беззбитковості',r.break_even_average===null?'—':num(r.break_even_average)+'<em> ₴</em>','Середня сума з договору з платежами*')}</div><div class="two-col"><div class="panel"><h2>Надходження проти повної вартості пакета</h2><div class="table-wrap"><table><tbody><tr><td>Прогноз усіх поступлень</td><td class="num">${money(r.gross_total)}</td></tr><tr><td>Ціна всього портфеля</td><td class="num">− ${money(options.price)}</td></tr><tr><td>Всі витрати, включно з безрезультатною роботою</td><td class="num">− ${money(r.cost_total)}</td></tr><tr class="total-row"><td>Результат до податків і фінансування</td><td class="num ${r.profit>=0?'positive-text':'negative-text'}">${signed(r.profit)}</td></tr></tbody></table></div><p class="fine">* Точка беззбитковості = (ціна + початкові + всі некомісійні витрати) / [очікувані договори з платежами × (1 − ефективна комісія)]. Склад, число платників, план витрат незмінні. Це не критерій цільової дохідності — для неї дивіться NPV.</p></div><div class="panel method-block"><h2>Від внеску договорів до ціни пакета</h2><p>По кожному договору: приведені очікувані збори мінус приведені прямі витрати.</p><div class="formula">Σ внесків договорів − PV спільних витрат − початкові витрати = гранична ціна</div><p>Після віднімання ціни всього пакета отримуємо NPV ${signed(r.npv)}. Ціну не розподіляємо довільно між договорами.</p><p style="margin-top:12px">Договорів із від’ємним сценарним внеском: <b>${num(negative)}</b>. Окремо на перевірці: <b>${num(r.count-r.ready_count)}</b>; вони не прирівнюються до неплатників.</p></div></div><div class="panel table-panel" style="margin-top:20px"><div class="panel-heading"><div><h2>Які сегменти створюють надходження</h2><p>Внесок враховує прямі витрати всіх записів сегмента, до спільних витрат і ціни покупки</p></div></div><div class="table-wrap"><table><thead><tr><th>Сегмент</th><th class="num">Договорів</th><th class="num">P для перевірених</th><th class="num">Із надходженнями</th><th class="num">Збори</th><th class="num">PV внеску</th></tr></thead><tbody>${segs}</tbody></table></div></div><div class="panel table-panel" style="margin-top:20px"><div class="panel-heading"><div><h2>Сценарне ранжування договорів</h2><p>Показано 25 договорів; однакові ймовірності в сегменті — явне припущення</p></div><button class="button secondary small" data-action="rank-order">${potentialOrder==='desc'?'Показати найнижчий внесок':'Показати найвищий внесок'}</button></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Сегмент</th><th class="num">P(платіж)*</th><th class="num">Очікувані збори</th><th class="num">Прямі витрати</th><th class="num">PV внеску</th></tr></thead><tbody>${rank.slice(0,25).map(x=>`<tr><td>${esc(x.loan_id)}</td><td>${NPL.SEGMENTS[x.segment].label}</td><td class="num">${pct(x.probability)}</td><td class="num">${money(x.gross)}</td><td class="num">${money(x.direct_cost)}</td><td class="num ${x.contribution<0?'negative-text':'positive-text'}">${money(x.contribution)}</td></tr>`).join('')}</tbody></table></div></div><p class="fine">* Сценарна ймовірність хоча б одного надходження за весь горизонт. Не класифікація фактичних майбутніх неплатників. Прямі витрати у таблиці номінальні; внесок враховує їхні строки.</p>`;
}
function renderCashflow(){
  const r=result;
  $('#tab-cashflow').innerHTML=`<div class="metrics">${metric('Потреба в коштах на старті',mln(options.price+options.startup),'Ціна пакета + початкові витрати')}${metric('Додатковий касовий дефіцит',mln(r.operating_cash_gap),'Понад початкову інвестицію')}${metric('Пікова потреба у капіталі',mln(r.funding_peak),'Без моделювання кредитної лінії','emphasis')}${metric('Стійка окупність',payback(r),'Після повернення коштів баланс не стає від’ємним')}</div><div class="panel"><div class="panel-heading"><div><h2>Накопичений грошовий результат</h2><p>Момент 0 включає покупку всього пакета й початкові витрати</p></div><button class="button secondary small" data-action="export-cashflow">↓ Календар CSV</button></div>${chart([{values:r.cash_balance,color:'#238565'}],{threshold:0,startAt:0,months:r.net.length,height:255})}<p class="fine">Якщо графік опускається нижче стартового відтоку, потрібен додатковий капітал. Прибуток, касовий баланс і NPV — різні показники.</p></div><div class="panel table-panel" style="margin-top:20px"><div class="panel-heading"><div><h2>Помесячний бюджет</h2><p>Всі категорії зведені в один грошовий потік; ціна і початкові витрати — тільки в моменті 0</p></div></div><div class="table-wrap calendar-table"><table><thead><tr><th>Місяць</th><th class="num">Збори</th><th class="num">Комісія</th><th class="num">Регулярні*</th><th class="num">Дії / юристи / інші</th><th class="num">Покупка + старт</th><th class="num">Чистий потік</th><th class="num">Баланс</th></tr></thead><tbody><tr><td>0</td><td class="num">0</td><td class="num">0</td><td class="num">0</td><td class="num">0</td><td class="num">${money(options.price+options.startup)}</td><td class="num">${signed(-options.price-options.startup)}</td><td class="num">${money(r.cash_balance[0])}</td></tr>${r.net.map((v,t)=>{const regular=['team','it','overhead','accounts'].reduce((s,k)=>s+r.categories[k][t],0),events=['actions','legal','review','extra'].reduce((s,k)=>s+r.categories[k][t],0);return `<tr><td>${t+1}</td><td class="num">${money(r.gross[t])}</td><td class="num">${money(r.categories.commission[t])}</td><td class="num">${money(regular)}</td><td class="num">${money(events)}</td><td class="num">0</td><td class="num ${v<0?'negative-text':''}">${signed(v)}</td><td class="num ${r.cash_balance[t+1]<0?'negative-text':'positive-text'}">${money(r.cash_balance[t+1])}</td></tr>`;}).join('')}</tbody></table></div><p class="fine" style="padding:0 20px 15px">* Команда, IT, накладні витрати та супровід договорів.</p></div>`;
}
function exportCashflow(){
  const r=result,keys=Object.keys(COST_LABELS),headers=['month','gross',...keys,'purchase','startup','net_cash','cash_balance'];
  const out=[headers.join(','),[0,0,...keys.map(()=>0),options.price,options.startup,-options.price-options.startup,r.cash_balance[0]].join(',')];
  r.net.forEach((v,t)=>out.push([t+1,r.gross[t],...keys.map(k=>r.categories[k][t]),0,0,v,r.cash_balance[t+1]].join(',')));
  download('npl-cashflow.csv','\uFEFF'+out.join('\r\n'),'text/csv;charset=utf-8');toast('Помесячний бюджет експортовано.');
}
